import{_ as t,a}from"./chunks/results-browser.CdA7rjFC.js";import{_ as i,o as s,c as o,a2 as r}from"./chunks/framework.Cv-B11KK.js";const k=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started.md","filePath":"getting-started.md","lastUpdated":1790343991000}'),n={name:"getting-started.md"};function l(d,e,c,h,p,b){return s(),o("div",null,[...e[0]||(e[0]=[r(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>bbtex adds a set of <strong>LaTeX —</strong> commands to BBEdit&#39;s Scripts menu, all backed by one small <code>bbtex</code> binary. This page gets you from nothing to a compiled PDF in about ten minutes, most of it spent waiting for MacTeX to download.</p><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p><strong>Current release: v0.1.0.</strong> This is the first release, and it&#39;s <a href="./about#totally-vibe-coded">totally vibe coded</a>. It works well on my Mac; if it doesn&#39;t on yours, please <a href="https://github.com/LouLouLibs/bbtex/issues" target="_blank" rel="noreferrer">open an issue</a>.</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>An Apple Silicon Mac. Packages are built and tested on the macOS version of the Mac that ran the release checks; Intel builds are not verified.</li><li><a href="https://www.barebones.com/products/bbedit/" target="_blank" rel="noreferrer">BBEdit</a>.</li><li>A TeX distribution: <a href="https://tug.org/mactex/" target="_blank" rel="noreferrer">MacTeX</a> or <a href="https://yihui.org/tinytex/" target="_blank" rel="noreferrer">TinyTeX</a>, which provide <code>latexmk</code>, <code>pdflatex</code>, <code>xelatex</code> and <code>lualatex</code>. With Biber, use version 2.21 or later with a matching biblatex.</li><li><a href="https://skim-app.sourceforge.io/" target="_blank" rel="noreferrer">Skim</a> for PDF viewing and SyncTeX.</li></ul><p>Optional:</p><ul><li><a href="https://tectonic-typesetting.github.io/" target="_blank" rel="noreferrer">Tectonic</a>, if you prefer it to latexmk.</li><li>Poppler&#39;s <code>pdftoppm</code> (<code>brew install poppler</code>), for equation previews.</li><li><a href="https://github.com/latex-lsp/texlab" target="_blank" rel="noreferrer">TexLab</a>, for completion and Go to Definition in BBEdit.</li></ul><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><h3 id="from-a-release-package" tabindex="-1">From a release package <a class="header-anchor" href="#from-a-release-package" aria-label="Permalink to &quot;From a release package&quot;">​</a></h3><ol><li>Download <code>bbtex-macos-arm64.bbpackage.zip</code> from the <a href="https://github.com/LouLouLibs/bbtex/releases" target="_blank" rel="noreferrer">Releases page</a> and unzip it.</li><li>Double-click <code>bbtex.bbpackage</code>. BBEdit installs it into <code>~/Library/Application Support/BBEdit/Packages/</code>.</li><li>Clear the download quarantine, or macOS blocks the unsigned binary with <em>&quot;Apple could not verify “bbtex” is free of malware&quot;</em>. Quit BBEdit, then run <code>xattr -dr com.apple.quarantine ~/Library/Application\\ Support/BBEdit/Packages/bbtex.bbpackage</code>.</li><li>Run <strong>Scripts → LaTeX — Doctor</strong> to check the TeX tools, Skim and the package layout.</li></ol><p>Starting from a brand-new Mac? The <a href="./install">clean install walkthrough</a> goes step by step, with a test document and uninstall instructions.</p><p>Preview on Save and the right-click Preview Selection service are optional installs; see <a href="./selection-preview#release-installation">equation previews</a>.</p><h3 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to &quot;From source&quot;">​</a></h3><p>You need <a href="https://opam.ocaml.org/doc/Install.html" target="_blank" rel="noreferrer">opam</a> with OCaml 4.14 or later (CI builds with 5.4.1).</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/LouLouLibs/bbtex.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bbtex</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">opam</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --deps-only</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # dune, uucp and uunf</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/install.sh</span></span></code></pre></div><p>This builds the binary, links it to <code>~/.local/bin/bbtex</code>, and links the scripts into BBEdit&#39;s Scripts folder. Install either the development scripts or the release package, not both, or the menu shows duplicates.</p><h2 id="set-up-bbedit" tabindex="-1">Set up BBEdit <a class="header-anchor" href="#set-up-bbedit" aria-label="Permalink to &quot;Set up BBEdit&quot;">​</a></h2><h3 id="keyboard-shortcuts" tabindex="-1">Keyboard shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard shortcuts&quot;">​</a></h3><p>Assign shortcuts in <strong>BBEdit → Settings → Menus &amp; Shortcuts</strong>, in the Scripts section:</p><table tabindex="0"><thead><tr><th>Script</th><th>Suggested shortcut</th></tr></thead><tbody><tr><td>LaTeX — Compile</td><td><kbd>⌘</kbd><kbd>K</kbd></td></tr><tr><td>LaTeX — Forward Search</td><td><kbd>⇧</kbd><kbd>⌘</kbd><kbd>J</kbd></td></tr><tr><td>LaTeX — Compile With…</td><td><kbd>⇧</kbd><kbd>⌘</kbd><kbd>K</kbd></td></tr><tr><td>LaTeX — Clean</td><td>none</td></tr></tbody></table><p>Remove any existing binding for those keys first. You can also assign keys in <strong>Window → Palettes → Scripts</strong>.</p><h3 id="skim-inverse-search" tabindex="-1">Skim inverse search <a class="header-anchor" href="#skim-inverse-search" aria-label="Permalink to &quot;Skim inverse search&quot;">​</a></h3><p>In <strong>Skim → Settings → Sync</strong>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>Preset</td><td>Custom</td></tr><tr><td>Command</td><td><code>/usr/local/bin/bbedit</code></td></tr><tr><td>Arguments</td><td><code>--line %line &quot;%file&quot;</code></td></tr></tbody></table><p>Now ⌘-click in Skim jumps back to the source line in BBEdit.</p><h2 id="first-build" tabindex="-1">First build <a class="header-anchor" href="#first-build" aria-label="Permalink to &quot;First build&quot;">​</a></h2><ol><li>Open a <code>.tex</code> file in BBEdit.</li><li>Press <kbd>⌘</kbd><kbd>K</kbd>. bbtex saves the document and any modified project inputs, compiles the root, and opens the PDF in Skim at the cursor.</li><li>Errors appear in the <strong>LaTeX Results</strong> browser. Click one to reach its line, fix it, and press <kbd>⌘</kbd><kbd>K</kbd> again. A successful build closes old results without opening a window.</li><li>Press <kbd>⇧</kbd><kbd>⌘</kbd><kbd>J</kbd> to show the cursor&#39;s position in the PDF.</li><li><strong>LaTeX — Show Build Results</strong> lists warnings and bad boxes without rebuilding; <strong>LaTeX — Open Build Log</strong> shows the full compiler output.</li></ol><p>A silent notification reports the root, engine, duration and diagnostic counts.</p><p><img src="`+t+'" alt="The compiled demo paper open in Skim"></p><p><img src="'+a+`" alt="LaTeX Results listing an undefined control sequence in model.tex, line 7"></p><h2 id="choose-the-engine-and-main-file" tabindex="-1">Choose the engine and main file <a class="header-anchor" href="#choose-the-engine-and-main-file" aria-label="Permalink to &quot;Choose the engine and main file&quot;">​</a></h2><p>Put TeXShop-style comments near the top of a file (bbtex reads the first 50 lines). Only these two are read; other <code>% !TEX</code> lines such as <code>spellcheck</code>, <code>options</code> or <code>% !BIB</code> are ignored:</p><div class="language-latex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">latex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">%!TEX program = xelatex</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">%!TEX root = ../main.tex</span></span></code></pre></div><ul><li><code>program</code> is <code>pdflatex</code> (the default), <code>xelatex</code>, <code>lualatex</code> or <code>tectonic</code>. The first three run through latexmk, which handles passes and BibTeX/Biber; Tectonic runs directly.</li><li><code>root</code> points an included chapter or table at the main document, relative to the file that contains it.</li></ul><p>Rather than typing these, press <kbd>⇧</kbd><kbd>⌘</kbd><kbd>K</kbd> and choose <strong>Configure Document…</strong>. The same <strong>Compile With…</strong> picker also runs a one-off build with another engine or a named profile. For settings shared across a project, such as the output directory, extra options and profiles, add a <a href="./project-builds#shared-project-settings"><code>.bbtex</code> file</a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./project-builds">Compiling projects</a>: <code>.bbtex</code> settings, profiles and cancellation.</li><li><a href="./bbedit-editing">Writing and editing</a>: environments, clippings and TexLab.</li><li><a href="./project-navigation">Project outline</a> and <a href="./citation-reference-pickers">citations and references</a>.</li><li><a href="./selection-preview">Equation previews</a>: manual, on save, or live.</li><li><a href="./setup-troubleshooting">Troubleshooting</a> if Doctor reports a problem.</li></ul>`,37)])])}const m=i(n,[["render",l]]);export{k as __pageData,m as default};
